mkdir -p /tmp/lamp-43-scripts && cat > /tmp/lamp-43-scripts/column.mjs <<'EOF'
// Prints the blocks of the gazebo interior, one y-slice per block, from a built structure (read-only).
import { load } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
const g = load(process.argv[2]);
const [x0, x1, z0, z1, y0, y1] = process.argv.slice(3).map(Number);
for (let y = y1; y >= y0; y--) {
  console.log(`y=${y}`);
  for (let z = z0; z <= z1; z++) {
    let row = `  z${z} `;
    for (let x = x0; x <= x1; x++) {
      const c = g.get ? g.get(x, y, z) : g.at(x, y, z);
      const name = c ? (typeof c === "string" ? c : c[0]) : "?";
      row += (name === "air" || !name ? "." : name.replace(/_/g, "").slice(0, 6).padEnd(7)) + " ";
    }
    console.log(row);
  }
}
EOF
